#!/usr/bin/env bash
# PreToolUse hook: refuse creating a migration file with Write (overwriting a generated one is fine)
# and any hand edit of db/schema.rb. See .claude/rules/050-migrations.md (Generated, Never Hand-Written).

INPUT=$(cat)
FILE_PATH=$(echo "$INPUT" | jq -r '.tool_input.file_path // empty')

case "$FILE_PATH" in
  */db/schema.rb)
    jq -n '{
      "hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny",
        "permissionDecisionReason": "db/schema.rb is generated by `bin/rails db:migrate`. Do not edit it by hand; change a migration and run it."
      }
    }'
    exit 0 ;;
  */db/migrate/*.rb) ;;
  *) exit 0 ;;
esac

[ -e "$FILE_PATH" ] && exit 0

jq -n '{
  "hookSpecificOutput": {
    "hookEventName": "PreToolUse",
    "permissionDecision": "deny",
    "permissionDecisionReason": "Migrations are generated, never hand-written. Run `bin/rails generate migration <Name> <fields>`, then edit the generated file. See .claude/rules/050-migrations.md."
  }
}'
